    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        max_divisor = int(num**0.5) + 1
        for i in range(3, max_divisor, 2):
            if num % i == 0:
                return False
        return True

    def is_nsw(num):
        reversed_num = int(str(num)[::-1])
        return num != reversed_num and is_prime(num) and is_prime(reversed_num)

    if n <= 0:
        return None

    primes = []
    num = 2
    while len(primes) < n:
        if is_nsw(num):
            primes.append(num)
        num += 1
    return primes[-1]
