def amicable_numbers_sum(limit):
    def sum_proper_divisors(n):
        if n == 1:
            return 0
        sum_div = 1  # 1 is a proper divisor for all numbers > 1
        sqrt_n = int(n ** 0.5)

        # If the number has square root as a divisor, consider the root once unless it's a square of a prime.
        if sqrt_n * sqrt_n == n:
            sum_div += sqrt_n
        else:
            for i in range(2, sqrt_n + 1):
                if n % i == 0:
                    sum_div += i
                    complement = n // i
                    if complement != i:
                        sum_div += complement
        return sum_div

    amicable_sum = 0

    # To avoid counting amicable pairs twice
    checked = set()
