def lps(str1):
    n = len(str1)
    # Create a DP table to store lengths of longest palindromic subsequence
    dp = [[0] * n for _ in range(n)]

    # A single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Check for subsequences of length 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if str1[i] == str1[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])

    return dp[0][n-1]
